from itertools import product
import heapq
from collections import Counter


def _dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    options = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        options.append([-1] + versions)

    best_vector = None
    best_versions = None
    for values in product(*options):
        chosen = {name: version for name, version in zip(names, values)
                  if version != -1}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in chosen and chosen[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, [])
               for name, version in chosen.items()):
            continue

        edges = {}
        valid = True
        for name, version in chosen.items():
            row = next(row for row in packages[name] if row["version"] == version)
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                target = dep["name"]
                if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(chosen):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue

        vector = tuple(chosen.get(name, -1) for name in order)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector, best_versions = vector, chosen

    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _build_dependency_solver(order, maximize):
    return lambda data: _dependency_solver(data, order, maximize)


def _component_06(data):
    def rounded(num, den):
        quotient, remainder = divmod(num, den)
        if data["rounding"] == "half_up" and remainder * 2 >= den:
            quotient += 1
        return quotient

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in selected}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts[group] <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(not low <= counts[group] <= high
               for group, (low, high) in ((g, (0, k)) for g in counts if g not in quotas)):
            continue
        active_ends = []
        feasible = True
        for job in sorted(selected, key=lambda j: (j["start"], j["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                feasible = False
                break
        if not feasible:
            continue
        sorted_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    index = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = 1 << index[data["source"]] if data["source"] in index else 0
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                choices.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | (1 << index[next_node] if next_node in index else 0)
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency_solver("descending", True),
    "component_02": _build_dependency_solver("descending", False),
    "component_03": _build_dependency_solver("ascending", True),
    "component_04": _build_dependency_solver("ascending", False),
    "component_05": _build_dependency_solver("descending", True),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}


def _dependency_solver(data, order, maximize):
    names = sorted(data["packages"], reverse=(order == "descending"))
    return _dependency_solver_impl(data, names, maximize)


def _dependency_solver_impl(data, order, maximize):
    packages = data["packages"]
    names_ascending = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    options = [[-1] + sorted(row["version"] for row in packages[name])
               for name in names_ascending]
    best_vector = best_versions = None
    for values in product(*options):
        chosen = {name: version for name, version in zip(names_ascending, values) if version != -1}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1] for name, bounds in roots.items()):
            continue
        if any(name in chosen and chosen[name] != v for name, v in pins.items()):
            continue
        if any(v in blocked.get(name, []) for name, v in chosen.items()):
            continue
        edges = {}
        valid = True
        for name, version in chosen.items():
            row = next(r for r in packages[name] if r["version"] == version)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue
        reachable, stack = set(), list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(chosen):
            continue
        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        vector = tuple(chosen.get(name, -1) for name in order)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector, best_versions = vector, chosen
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}
